<script setup lang="ts">
import {ref,watch,onUnmounted} from 'vue'
import {ApiError} from '../../../api/auth'
import {getMarketVersionReferences,type VersionReferenceReport} from '../../../api/marketVersionReferences'
import {label,time} from './marketDataPresentation'
const props=defineProps<{instrumentId:string;versionId:string;actorUserId:string}>()
const emit=defineEmits<{accessDenied:[error:unknown]}>()
const data=ref<VersionReferenceReport|null>(null),busy=ref(false),error=ref(''),stale=ref(false),revoked=ref(false)
let epoch=0,alive=true
const names={prediction:'预测与分析',scheduler:'任务调度',notification:'预警与通知'}
const reasons:Record<string,string>={REFERENCE_QUERY_BUSY:'本服务正在处理另一项引用查询',REFERENCE_QUERY_UNAVAILABLE:'本库引用暂无法查询',REFERENCE_QUERY_BUDGET:'查询耗时达到本次界限',REFERENCE_ROW_LIMIT:'记录数超过本次完整检查范围',REFERENCE_JSON_LIMIT:'快照体积超过本次检查范围',REFERENCE_JSON_INVALID:'部分快照格式无法核对',REFERENCE_SERVICE_UNAVAILABLE:'业务服务暂不可用',REFERENCE_RESPONSE_INVALID:'业务服务返回结果无法核对'}
async function inspect(){if(busy.value||revoked.value)return;const n=epoch;busy.value=true;error.value='';try{const result=await getMarketVersionReferences(props.instrumentId,props.versionId);if(alive&&n===epoch){data.value=result;stale.value=false}}
 catch(err){if(!alive||n!==epoch)return;if(err instanceof ApiError&&(err.status===401||err.status===403&&err.code==='ACCESS_DENIED')){epoch++;data.value=null;stale.value=false;busy.value=false;revoked.value=true;error.value='管理员访问已失效，请重新确认账号';emit('accessDenied',err);return}error.value=(err as Error).message||'引用暂无法核对';stale.value=data.value!==null}
 finally{if(n===epoch)busy.value=false}}
watch(()=>[props.actorUserId,props.instrumentId,props.versionId],()=>{epoch++;data.value=null;busy.value=false;error.value='';stale.value=false;revoked.value=false})
onUnmounted(()=>{alive=false;epoch++})
</script>
<template><section class="version-references" aria-label="固定版本引用检查" :aria-busy="busy"><h3>行情版本引用检查</h3><p>仅查看这份固定版本的候选引用，不修改数据，也不调用AI或行情数据源。</p><button type="button" data-test="inspect-version-references" :disabled="busy||revoked" @click="inspect">{{data?'刷新引用检查':'检查此版本引用'}}</button><p v-if="busy" role="status">正在核对三个业务服务，请勿重复点击…</p><p v-if="error" role="alert">{{error}}<span v-if="stale"> · 本次未刷新，下方保留原结果和查询时间。</span></p><template v-if="data"><p class="reference-warning">以下是包含该版本标识的候选记录行数，同一业务可能出现多行，不能加总当作业务数量。各服务分别查询，可能存在在途记录；即使全部为零，也不能直接据此停用或删除版本。</p><dl><dt>行情版本</dt><dd>{{data.versionId}}</dd><dt>来源及状态</dt><dd>{{data.provider}} · {{label(data.priceBasis)}} · {{label(data.versionState)}}</dd><dt>查询时当前头</dt><dd>{{data.currentHead?'是':'否'}}（仅为查询时点状态）</dd><dt>本次查询时间</dt><dd>{{time(data.startedAt)}} ～ {{time(data.finishedAt)}}</dd></dl><p v-if="data.state==='PARTIAL'" role="status">部分服务或记录未能核对；未知不表示没有引用。</p><p v-else>本次各服务查询已完成，仍须注意跨服务时差与在途记录。</p><details v-for="owner in data.owners" :key="owner.owner" :data-owner="owner.owner"><summary>{{names[owner.owner]}} · {{owner.state==='COMPLETE'?'本次已核对':owner.state==='PARTIAL'?'部分未能核对':'未能核对'}}</summary><p class="md-muted">该服务查询时间：{{time(owner.queriedAt)}}</p><p v-if="owner.state==='UNKNOWN'">{{reasons[owner.reasonCode||'']||'暂无法核对'}}</p><div v-else class="md-table" role="region" :aria-label="names[owner.owner]+'候选引用'" tabindex="0"><table><thead><tr><th>记录类别</th><th>候选记录行数</th><th>核对状态</th></tr></thead><tbody><tr v-for="group in owner.groups" :key="group.category"><td>{{group.label}}</td><td>{{group.state==='COMPLETE'?group.rows+'条记录':'未知'}}</td><td>{{group.state==='COMPLETE'?'本次完整检查':reasons[group.reasonCode||'']||'暂无法核对'}}</td></tr></tbody></table></div></details></template></section></template>
<style scoped>.version-references{border:1px solid var(--border);border-radius:8px;padding:16px;margin:16px 0 24px;overflow-wrap:anywhere}.reference-warning{border-left:3px solid var(--accent);padding:8px 12px;background:var(--canvas);line-height:1.7}.version-references table{min-width:520px}.version-references button:focus-visible{outline:3px solid var(--accent);outline-offset:3px}</style>
